<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Models\{AbkSubmission,Customer,DailyRecord,FeedType,LivestockGroup,Revenue};
use App\Services\{AbkSubmissionService,ProofStorage};
use Illuminate\Http\Request;

class AbkApiController extends Controller {
 public function me(Request $request) { $e=$this->employee($request); return response()->json(['data'=>['id'=>$e->id,'name'=>$e->name,'username'=>$e->api_username,'type'=>$e->abk_type,'capabilities'=>$this->capabilities($e->abk_type)]]); }
 public function groups(Request $request) { $e=$this->employee($request);$v=$request->validate(['species'=>'required|in:AYAM,LELE']);$this->scope($e,$v['species']);return response()->json(['data'=>LivestockGroup::where('species',$v['species'])->where('status','ACTIVE')->orderBy('name')->get(['id','code','name','location','start_date'])]); }
 public function feeds(Request $request) { $e=$this->employee($request);$v=$request->validate(['species'=>'required|in:AYAM,LELE']);$this->scope($e,$v['species']);return response()->json(['data'=>FeedType::where('species',$v['species'])->where('is_active',true)->orderBy('name')->get(['id','name','species'])]); }
 public function customers(Request $request) { $this->scope($this->employee($request),'AYAM'); return response()->json(['data'=>Customer::orderBy('name')->paginate($this->perPage($request))]); }
 public function daily(Request $request) { $e=$this->employee($request);$v=$request->validate(['species'=>'required|in:AYAM,LELE','from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d|after_or_equal:from','group_id'=>'nullable|integer']);$this->scope($e,$v['species']);$q=DailyRecord::with(['group','feedUsages.feedType','eggHarvests'])->whereHas('group',fn($q)=>$q->where('species',$v['species']));if(filled($v['from']??null))$q->where('record_date','>=',$v['from']);if(filled($v['to']??null))$q->where('record_date','<=',$v['to']);if(filled($v['group_id']??null))$q->where('group_id',$v['group_id']);return response()->json($q->latest('record_date')->paginate($this->perPage($request))); }
 public function dailyShow(Request $request,DailyRecord $record){$record->load(['group','feedUsages.feedType','eggHarvests']);$this->scope($this->employee($request),$record->group->species);return response()->json(['data'=>$record]);}
 public function eggSales(Request $request) { $this->scope($this->employee($request),'AYAM');$v=$request->validate(['from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d|after_or_equal:from','customer_id'=>'nullable|integer|exists:customers,id','payment_status'=>'nullable|in:UNPAID,PARTIALLY_PAID,PAID','approval_status'=>'nullable|in:NOT_REQUIRED,SUBMITTED,APPROVED,REJECTED']);$q=Revenue::with(['eggDetails','customer'])->where('revenue_type','EGG_SALE');foreach(['customer_id','payment_status','approval_status']as$field)if(filled($v[$field]??null))$q->where($field,$v[$field]);if(filled($v['from']??null))$q->where('transaction_date','>=',$v['from']);if(filled($v['to']??null))$q->where('transaction_date','<=',$v['to']);return response()->json($q->latest('transaction_date')->paginate($this->perPage($request))); }
 public function eggShow(Request $request,Revenue $revenue){$this->scope($this->employee($request),'AYAM');abort_unless($revenue->revenue_type==='EGG_SALE',404);return response()->json(['data'=>$revenue->load(['eggDetails','customer'])]);}
 public function dailySubmissions(Request $request) { return $this->submissions($request,'daily'); }
 public function eggSubmissions(Request $request) { return $this->submissions($request,'egg'); }
 public function submissions(Request $request,string $domain) { $e=$this->employee($request);$kinds=$domain==='daily'?['DAILY_AYAM','DAILY_LELE']:['EGG_SALE'];if($domain==='egg')$this->scope($e,'AYAM');$q=AbkSubmission::with(['employee:id,name','reviewer:id,name'])->whereIn('kind',$kinds);if($e->abk_type!=='BOTH')$q->where('species',$e->abk_type);if($request->filled('status'))$q->where('status',$request->validate(['status'=>'in:DRAFT,APPROVED,REJECTED'])['status']);return response()->json($q->latest()->paginate($this->perPage($request))); }
 public function createDaily(Request $request,AbkSubmissionService $service) { $e=$this->employee($request);$v=$request->validate(['species'=>'required|in:AYAM,LELE']+$this->dailyApiRules(true));$species=$v['species'];validator($v,$this->dailyRules(true,$species))->validate();$kind='DAILY_'.$species;unset($v['species']);$this->validateDailyReferences($v,$species);$submission=$service->create($kind,$v,$e,$request->header('Idempotency-Key'));return response()->json(['data'=>$submission],201); }
 public function reviseDaily(Request $request,DailyRecord $record,AbkSubmissionService $service) { $e=$this->employee($request);$record->load('group');$species=$record->group->species;$this->scope($e,$species);$v=$request->validate($this->dailyApiRules(false));validator($v,$this->dailyRules(false,$species))->validate();$v+=['group_id'=>$record->group_id,'record_date'=>$record->record_date->toDateString()];$this->validateDailyReferences($v,$species);$submission=$service->create('DAILY_'.$species,$v,$e,$request->header('Idempotency-Key'),'daily_records',$record->id);return response()->json(['data'=>$submission],201); }
 public function updateDaily(Request $request,AbkSubmission $submission,AbkSubmissionService $service) { abort_unless(str_starts_with($submission->kind,'DAILY_'),404);$v=$request->validate($this->dailyApiRules(false));validator($v,$this->dailyRules(false,$submission->species))->validate();$v+=['group_id'=>$submission->payload['group_id'],'record_date'=>$submission->payload['record_date']];$this->validateDailyReferences($v,$submission->species);return response()->json(['data'=>$service->update($submission,$v,$this->employee($request))]); }
 public function createEgg(Request $request,AbkSubmissionService $service,ProofStorage $proofs) { $e=$this->employee($request);$v=$request->validate($this->eggRules());unset($v['proof']);$this->validateCustomerChoice($v);$v['revenue_type']='EGG_SALE';$submission=null;$proofs->replace($request->file('proof'),'abk-submissions',null,function($proof)use(&$submission,$service,$v,$e,$request){$submission=$service->create('EGG_SALE',$v,$e,$request->header('Idempotency-Key'));if($proof)$submission->update(['proof_path'=>$proof['path'],'proof_url'=>$proof['url']]);});return response()->json(['data'=>$submission],201); }
 public function reviseEgg(Request $request,Revenue $revenue,AbkSubmissionService $service,ProofStorage $proofs) {
  abort_unless($revenue->revenue_type==='EGG_SALE',404);$v=$request->validate($this->eggRules());unset($v['proof']);$this->validateCustomerChoice($v);$v['revenue_type']='EGG_SALE';$submission=null;
  $proofs->replace($request->file('proof'),'abk-submissions',null,function($proof)use(&$submission,$service,$v,$request,$revenue){$submission=$service->create('EGG_SALE',$v,$this->employee($request),$request->header('Idempotency-Key'),'revenues',$revenue->id);if($proof)$submission->update(['proof_path'=>$proof['path'],'proof_url'=>$proof['url']]);});
  return response()->json(['data'=>$submission],201);
 }
 public function updateEgg(Request $request,AbkSubmission $submission,AbkSubmissionService $service,ProofStorage $proofs) {
  abort_unless($submission->kind==='EGG_SALE',404);$v=$request->validate($this->eggRules());unset($v['proof']);$this->validateCustomerChoice($v);$v['revenue_type']='EGG_SALE';$updated=null;
  $proofs->replace($request->file('proof'),'abk-submissions',$submission->proof_path,function($proof)use(&$updated,$service,$submission,$v,$request){$updated=$service->update($submission,$v,$this->employee($request));if($proof)$updated->update(['proof_path'=>$proof['path'],'proof_url'=>$proof['url']]);});
  return response()->json(['data'=>$updated?->fresh()]);
 }
 private function employee(Request $r){return $r->attributes->get('abk_employee');}
 private function scope($employee,string $species):void{abort_unless($employee->canAccessSpecies($species),403,'Akses ABK tidak sesuai jenis data.');}
 private function capabilities(string $type):array{return ['daily_ayam'=>in_array($type,['AYAM','BOTH']),'daily_lele'=>in_array($type,['LELE','BOTH']),'egg_sales'=>in_array($type,['AYAM','BOTH'])];}
 private function dailyApiRules(bool $identity):array{$rules=$identity?['record_date'=>'required|date_format:Y-m-d','group_id'=>'required|integer|exists:livestock_groups,id']:[];$rules+=['mortality'=>'required|integer|min:0','notes'=>'nullable|string|max:3000','feeds'=>$identity?'required|array|min:1|max:30':'nullable|array|max:30','feeds.*.feed_type_id'=>'required|integer|exists:feed_types,id','feeds.*.morning_kg'=>'required|numeric|min:0','feeds.*.noon_kg'=>'required|numeric|min:0','feeds.*.evening_kg'=>'nullable|numeric|min:0','eggs'=>'nullable|array'];foreach(['UTUH','PECAH','REJECT']as$c){$rules["eggs.$c.weight_kg"]='nullable|numeric|min:0';$rules["eggs.$c.quantity_pieces"]='nullable|integer|min:0';}return $rules;}
 private function dailyRules(bool $identity,string $species):array{$rules=array_merge($identity?['record_date'=>'required|date_format:Y-m-d','group_id'=>'required|integer|exists:livestock_groups,id']:[],['mortality'=>'required|integer|min:0','notes'=>'nullable|string|max:3000','feeds'=>$identity?'required|array|min:1|max:30':'nullable|array|max:30','feeds.*.feed_type_id'=>'required|integer|exists:feed_types,id','feeds.*.morning_kg'=>'required|numeric|min:0','feeds.*.noon_kg'=>'required|numeric|min:0','feeds.*.evening_kg'=>$species==='LELE'?'required|numeric|min:0':'prohibited']);if($species==='AYAM')foreach(['UTUH','PECAH','REJECT']as$c){$rules["eggs.$c.weight_kg"]='required|numeric|min:0';$rules["eggs.$c.quantity_pieces"]='required|integer|min:0';}else$rules['eggs']='prohibited';return $rules;}
 private function validateDailyReferences(array $payload,string $species):void{$group=LivestockGroup::findOrFail($payload['group_id']);if($group->species!==$species||$group->status!=='ACTIVE')throw \Illuminate\Validation\ValidationException::withMessages(['group_id'=>'Grup harus aktif dan sesuai scope.']);foreach($payload['feeds']??[]as$line)if(FeedType::findOrFail($line['feed_type_id'])->species!==$species)throw \Illuminate\Validation\ValidationException::withMessages(['feeds'=>'Jenis pakan tidak sesuai spesies.']);}
 private function validateCustomerChoice(array $payload):void{if(filled($payload['customer_id']??null)&&is_array($payload['new_customer']??null))throw \Illuminate\Validation\ValidationException::withMessages(['customer_id'=>'Pilih pelanggan tersimpan atau pelanggan baru, bukan keduanya.']);}
 private function perPage(Request $request):int{$v=$request->validate(['per_page'=>'nullable|integer|min:1|max:100']);return (int)($v['per_page']??30);}
 private function eggRules():array{return ['transaction_date'=>'required|date_format:Y-m-d','customer_id'=>'nullable|required_without:new_customer|integer|exists:customers,id','new_customer'=>'nullable|required_without:customer_id|array','new_customer.name'=>'required_with:new_customer|string|max:255','new_customer.phone'=>'required_with:new_customer|string|max:50','new_customer.customer_type'=>'required_with:new_customer|in:WARUNG,AGEN','new_customer.notes'=>'nullable|string|max:3000','payment_method'=>'required|in:CASH,DIRECT_TRANSFER','direct_transfer_date'=>'nullable|required_if:payment_method,DIRECT_TRANSFER|date_format:Y-m-d|before_or_equal:today','payment_status'=>'nullable|in:UNPAID,PAID','paid_date'=>'nullable|required_if:payment_status,PAID|date_format:Y-m-d|before_or_equal:today','details'=>'required|array|min:1|max:3','details.*.egg_category'=>'required|in:UTUH,PECAH,REJECT|distinct','details.*.weight_kg'=>'required|numeric|min:0','details.*.quantity_pieces'=>'required|integer|min:0','details.*.price_per_kg_idr'=>'required|numeric|min:0','details.*.notes'=>'nullable|string|max:1000','proof'=>'nullable|file|mimes:jpg,jpeg,png|max:5120'];}
}
